package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"path/filepath"
	"strings"
	"text/template"
)

const TemplateStr = `
// Code generated by go generate; DO NOT EDIT.
// This file was generated by genenum.go

package {{.Package}}

import "fmt"

var names{{.Type}} = map[{{.Type}}]string{
{{range .Entries}}{{.Value}}: "{{.Name}}",{{if .Alert}} // {{.Alert}}{{end}}
{{end}}
}

func (v {{.Type}}) String() string {
    return names{{.Type}}[v]
}

{{range .Entries}}
type {{.Name}}Error struct {
    Description string
}

func (v {{.Name}}Error) Error() string {
    return fmt.Sprintf("HTTP {{.Value}} %s", v.Description) 
}

{{if .Alert}}
func (v {{.Name}}Error) Alert() string {
    return "{{.Alert}}"
}
{{end}}
{{end}}
`

var tmpl = template.Must(template.New("reset").Parse(TemplateStr))

type structInfo struct {
	Name   string
	Fields []*ast.Field
	Lines  []string
}

type pkgInfo struct {
	Package string
	Structs []*structInfo
}

func main() {
	rootDir := "../.."
	pkgs := map[string]*pkgInfo{}

	fset := token.NewFileSet()
	err := filepath.WalkDir(rootDir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			name := d.Name()
			if path != rootDir && strings.HasPrefix(name, ".") {
				return filepath.SkipDir
			}
			return nil
		}

		if !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") || d.Name() == "reset.gen.go" {
			return nil
		}

		file, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
		if err != nil {
			fmt.Printf("parse %s: %v\n", path, err)
			return nil
		}
		dir := filepath.Dir(path)
		ast.Inspect(file, func(n ast.Node) bool {
			genDecl, ok := n.(*ast.GenDecl)
			if !ok || genDecl.Tok != token.TYPE {
				return true
			}

			for _, spec := range genDecl.Specs {
				typeSpec, ok := spec.(*ast.TypeSpec)
				if !ok {
					continue
				}
				st, isStruct := typeSpec.Type.(*ast.StructType)
				if !isStruct {
					continue
				}
				if !hasMarker(genDecl.Doc, typeSpec.Doc) {
					continue
				}
				p := pkgs[dir]
				if p == nil {
					p = &pkgInfo{Package: file.Name.Name}
					pkgs[dir] = p
				}
				p.Structs = append(p.Structs, &structInfo{Name: typeSpec.Name.Name, Fields: st.Fields.List})
			}
			return false
		})

		return nil
	})

	if err != nil {
		fmt.Printf("ошибка при сканировании директории: %v\n", err) // TODO: Поправить на логгер?
	}
}

func hasMarker(groups ...*ast.CommentGroup) bool {

	for _, group := range groups {
		if group == nil {
			continue
		}
		for _, comment := range group.List {
			if strings.TrimSpace(strings.TrimPrefix(comment.Text, "//")) == "generate:reset" {
				return true
			}
		}
	}
	return false
}
